import sys

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()
    return data

def main():
    data = read_input()
    N = int(data[0])
    ring = list(map(int, data[1:]))

    # Create the matrix for the system of equations
    matrix = [[0] * N for _ in range(N)]
    for i in range(N):
        matrix[i][(i - 1) % N] = 1
        matrix[i][i] = -2
        matrix[i][(i + 1) % N] = 1

    # Add the right-hand side of the equations
    for i in range(N):
        matrix[i].append(ring[i])

    # Gaussian elimination
    for i in range(N):
        # Find a row with a non-zero element in the current column
        if matrix[i][i] == 0:
            for j in range(i + 1, N):
                if matrix[j][i] != 0:
                    matrix[i], matrix[j] = matrix[j], matrix[i]
                    break

        # Normalize the current row
        factor = matrix[i][i]
        for j in range(N + 1):
            matrix[i][j] //= factor

        # Eliminate the current column in the other rows
        for j in range(N):
            if j != i:
                factor = matrix[j][i]
                for k in range(N + 1):
                    matrix[j][k] -= factor * matrix[i][k]

    # Extract the solution
    solution = [matrix[i][-1] for i in range(N)]

    # Print the solution
    for num in solution:
        print(num)

if __name__ == "__main__":
    main()
